import type { Editor } from "@tiptap/core";
import type { ExportPayload } from "../exchange";
import { createRevisionSnapshot } from "../revision-history";
import {
  FOLIO_CONTENT_SAVED,
  loadFolioContentSnapshotFromIdb,
  saveFolioTypstToIdb,
  type FolioContentSavedDetail,
} from "../idb";
import { htmlToTypst, typstToHtml, reconcileTypstSource } from "./document";
import { compileTypstSource, type TypstCompilation } from "./client";
import {
  loadTypstSourceDraft,
  saveTypstSourceDraft,
  clearTypstSourceDraft,
} from "./source-drafts";

export interface TypstSessionState {
  source: string;
  dirty: boolean;
  conflict: boolean;
  status: string;
  error: string;
  pages: string[];
  pdfUrl: string;
  applying: boolean;
}
export interface TypstSession {
  changeSource(source: string): void;
  apply(): Promise<void>;
  discard(): Promise<void>;
  refreshProof(): void;
  destroy(): void;
}
export interface TypstSessionOptions {
  editor: Editor;
  folioId: string;
  readOnly: boolean;
  onState(state: TypstSessionState): void;
  getPayload(source: string): Promise<ExportPayload>;
  onPages(pageCount: number): void;
}

export interface TypstSessionDependencies {
  loadSnapshot: typeof loadFolioContentSnapshotFromIdb;
  saveSource: typeof saveFolioTypstToIdb;
  loadDraft: typeof loadTypstSourceDraft;
  saveDraft: typeof saveTypstSourceDraft;
  clearDraft: typeof clearTypstSourceDraft;
  compile: typeof compileTypstSource;
  saveRevision: typeof createRevisionSnapshot;
}

/** One folio owns its source draft, compiler cancellation and proof object URLs. */
export async function createTypstSession(
  options: TypstSessionOptions,
  overrides: Partial<TypstSessionDependencies> = {},
): Promise<TypstSession> {
  const { editor, folioId } = options;
  const deps: TypstSessionDependencies = {
    loadSnapshot: loadFolioContentSnapshotFromIdb,
    saveSource: saveFolioTypstToIdb,
    loadDraft: loadTypstSourceDraft,
    saveDraft: saveTypstSourceDraft,
    clearDraft: clearTypstSourceDraft,
    compile: compileTypstSource,
    saveRevision: createRevisionSnapshot,
    ...overrides,
  };
  let destroyed = false;
  let applying = false;
  let replacing = false;
  let revision = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let controller: AbortController | undefined;
  let baselineHtml = editor.getHTML();
  const visualHistory = new Set([baselineHtml]);
  const snapshot = await deps.loadSnapshot(folioId);
  let baseSource = snapshot?.typstSource;
  let committedHtml = snapshot?.html ?? baselineHtml;
  const recovered = await deps.loadDraft(folioId);
  baselineHtml = editor.getHTML();
  visualHistory.add(baselineHtml);
  let cleanSource =
    baseSource !== undefined
      ? reconcileTypstSource(baseSource, baselineHtml)
      : htmlToTypst(baselineHtml);
  const state: TypstSessionState = {
    source: recovered?.source ?? cleanSource,
    dirty: Boolean(recovered && recovered.source !== cleanSource),
    conflict: Boolean(
      recovered &&
        recovered.source !== cleanSource &&
        recovered.baseSource !== (baseSource ?? cleanSource),
    ),
    status: recovered ? "Recovered source draft" : "Preparing proof…",
    error: "",
    pages: [],
    pdfUrl: "",
    applying: false,
  };
  if (recovered && state.dirty) baseSource = recovered.baseSource;
  function emit() {
    if (destroyed) return;
    state.applying = applying;
    const editable = !options.readOnly && !state.dirty && !applying;
    if (editor.isEditable !== editable) editor.setEditable(editable, false);
    options.onState({ ...state, pages: [...state.pages] });
  }
  function sourceEvent() {
    window.dispatchEvent(
      new CustomEvent("twyne:typst-source-state", {
        detail: { folioId, source: state.source, pending: state.dirty },
      }),
    );
  }
  function draft() {
    if (destroyed || options.readOnly) return;
    void deps
      .saveDraft({
        folioId,
        source: state.source,
        baseSource: baseSource ?? cleanSource,
        updatedAt: Date.now(),
      })
      .catch((error) => {
        if (destroyed) return;
        state.error =
          error instanceof Error
            ? error.message
            : "Source could not be saved on this device.";
        emit();
      });
  }
  function cancel() {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
    controller?.abort();
    controller = undefined;
    revision++;
  }
  function releaseProof() {
    state.pages.forEach((url) => URL.revokeObjectURL(url));
    if (state.pdfUrl) URL.revokeObjectURL(state.pdfUrl);
  }
  async function compile(): Promise<TypstCompilation | undefined> {
    cancel();
    const currentRevision = revision;
    const source = state.source;
    const task = new AbortController();
    controller = task;
    state.status = "Typesetting…";
    state.error = "";
    emit();
    try {
      const payload = await options.getPayload(source);
      task.signal.throwIfAborted();
      const compiled = await deps.compile(source, {
        payload,
        signal: task.signal,
        onProgress: (status) => {
          if (!destroyed && currentRevision === revision) {
            state.status = status;
            emit();
          }
        },
      });
      if (destroyed || currentRevision !== revision || source !== state.source)
        return undefined;
      const urls = compiled.pages.map((svg) =>
        URL.createObjectURL(new Blob([svg], { type: "image/svg+xml" })),
      );
      const pdfUrl = URL.createObjectURL(compiled.pdf);
      releaseProof();
      state.pages = urls;
      state.pdfUrl = pdfUrl;
      state.status = `${compiled.pageCount} ${compiled.pageCount === 1 ? "page" : "pages"}${state.dirty ? " · source draft" : ""}`;
      options.onPages(compiled.pageCount);
      emit();
      return compiled;
    } catch (error) {
      if (destroyed || task.signal.aborted || currentRevision !== revision)
        return undefined;
      state.status = state.pages.length
        ? "Showing last valid proof"
        : "Proof unavailable";
      state.error =
        error instanceof Error
          ? error.message
          : "The source could not be typeset.";
      emit();
      return undefined;
    } finally {
      if (controller === task) controller = undefined;
    }
  }
  function schedule() {
    cancel();
    timer = setTimeout(() => {
      timer = undefined;
      void compile();
    }, 450);
  }
  function editorUpdated() {
    if (destroyed || replacing || applying) return;
    const html = editor.getHTML();
    if (state.dirty) {
      if (html !== baselineHtml) {
        state.conflict = true;
        state.error =
          "The visual manuscript changed. Keep a source copy before discarding or resolving this draft.";
        emit();
      }
      return;
    }
    baselineHtml = html;
    visualHistory.add(html);
    if (visualHistory.size > 100)
      visualHistory.delete(visualHistory.values().next().value!);
    cleanSource = reconcileTypstSource(state.source, html);
    state.source = cleanSource;
    sourceEvent();
    emit();
    schedule();
  }
  function saved(event: Event) {
    const rec = (event as CustomEvent<FolioContentSavedDetail>).detail;
    if (
      destroyed ||
      applying ||
      rec?.folioId !== folioId ||
      rec.origin === "remote" ||
      rec.typstSource === undefined
    )
      return;
    if (visualHistory.has(rec.html)) committedHtml = rec.html;
    if (visualHistory.has(rec.html) && rec.html !== baselineHtml) {
      // A debounced save can complete after another keystroke. Never project
      // that older local snapshot back over the live editor/source draft.
      baseSource = rec.typstSource;
      if (state.dirty) draft();
      return;
    }
    if (state.dirty) {
      // A save already queued by the visual editor before source editing began.
      if (rec.html === baselineHtml && rec.typstSource === cleanSource) {
        baseSource = rec.typstSource;
        draft();
      } else if (rec.typstSource !== baseSource) {
        state.conflict = true;
        state.error =
          "A newer manuscript was saved while you edited source. Download your draft, then discard it to load the latest revision.";
      }
      emit();
      return;
    }
    if (!visualHistory.has(rec.html)) return;
    baseSource = rec.typstSource;
    baselineHtml = editor.getHTML();
    cleanSource = reconcileTypstSource(rec.typstSource, baselineHtml);
    state.source = cleanSource;
    sourceEvent();
    emit();
    schedule();
  }
  function remoteChanged(event: Event) {
    const rec = (
      event as CustomEvent<{
        folioId: string;
        source: string;
        html: string;
        intentionalReplacement?: boolean;
      }>
    ).detail;
    if (destroyed || rec?.folioId !== folioId || applying) return;
    if (state.dirty) {
      if (rec.source !== baseSource) {
        state.conflict = true;
        state.error =
          "A newer manuscript arrived while you edited source. Download your draft before discarding it to load the latest revision.";
        emit();
      }
      return;
    }
    if (
      !rec.intentionalReplacement &&
      editor.getHTML() !== committedHtml &&
      editor.getHTML() !== rec.html
    ) {
      state.source = reconcileTypstSource(state.source, editor.getHTML());
      state.dirty = true;
      state.conflict = true;
      state.error =
        "A newer manuscript arrived before your visual edits were saved. Your local draft is preserved; download it before loading the newer revision.";
      draft();
      sourceEvent();
      emit();
      return;
    }
    committedHtml = rec.html;
    baseSource = rec.source;
    cleanSource = rec.source;
    state.source = rec.source;
    replacing = true;
    try {
      if (editor.getHTML() !== rec.html) {
        window.dispatchEvent(
          new CustomEvent("twyne:typst-applying", { detail: { folioId } }),
        );
        editor.commands.setContent(rec.html, { emitUpdate: false });
      }
      baselineHtml = editor.getHTML();
    } finally {
      replacing = false;
    }
    sourceEvent();
    emit();
    schedule();
  }
  function requestSource(event: Event) {
    const detail = (
      event as CustomEvent<{
        folioId?: string;
        source?: string;
        pending?: boolean;
      }>
    ).detail;
    if (detail && (!detail.folioId || detail.folioId === folioId)) {
      detail.source = state.source;
      detail.pending = state.dirty;
    }
  }
  editor.on("update", editorUpdated);
  window.addEventListener(FOLIO_CONTENT_SAVED, saved);
  window.addEventListener("twyne:typst-remote-change", remoteChanged);
  window.addEventListener("twyne:request-typst-source", requestSource);
  emit();
  sourceEvent();
  schedule();
  return {
    changeSource(source) {
      if (destroyed || options.readOnly || applying || source === state.source)
        return;
      state.source = source;
      state.dirty = source !== cleanSource;
      state.error = "";
      if (!state.dirty) state.conflict = false;
      draft();
      sourceEvent();
      emit();
      schedule();
    },
    async apply() {
      if (destroyed || options.readOnly || applying || !state.dirty) return;
      if (state.conflict) {
        state.error =
          "Resolve the newer manuscript conflict before applying this draft.";
        emit();
        return;
      }
      applying = true;
      emit();
      try {
        const source = state.source;
        const result = await compile();
        if (!result || destroyed || state.source !== source) return;
        const html = typstToHtml(source);
        window.dispatchEvent(
          new CustomEvent("twyne:typst-applying", { detail: { folioId } }),
        );
        await deps.saveSource(folioId, source, html, baseSource ?? null);
        window.dispatchEvent(
          new CustomEvent("twyne:typst-source-committed", {
            detail: { folioId, source, html },
          }),
        );
        await deps.clearDraft(folioId);
        await deps.saveRevision({
          folioId,
          html,
          typstSource: source,
          source: "manual",
          label: "Typst source applied",
        });
        if (destroyed) return;
        baseSource = source;
        cleanSource = source;
        replacing = true;
        try {
          editor.commands.setContent(html, { emitUpdate: true });
          baselineHtml = editor.getHTML();
          committedHtml = baselineHtml;
        } finally {
          replacing = false;
        }
        state.dirty = false;
        state.conflict = false;
        state.error = "";
        state.status = "Source applied · saved on this device";
        sourceEvent();
      } catch (error) {
        state.error =
          error instanceof Error
            ? error.message
            : "Source could not be applied.";
        if (state.error.includes("manuscript changed")) state.conflict = true;
        draft();
      } finally {
        applying = false;
        emit();
      }
    },
    async discard() {
      if (destroyed || applying) return;
      applying = true;
      emit();
      cancel();
      try {
        const latest = await deps.loadSnapshot(folioId);
        if (destroyed) return;
        baseSource = latest?.typstSource;
        cleanSource = baseSource ?? htmlToTypst(editor.getHTML());
        state.source = cleanSource;
        state.dirty = false;
        state.conflict = false;
        state.error = "";
        replacing = true;
        try {
          editor.commands.setContent(latest?.html ?? typstToHtml(cleanSource), {
            emitUpdate: false,
          });
          baselineHtml = editor.getHTML();
          committedHtml = baselineHtml;
        } finally {
          replacing = false;
        }
        await deps.clearDraft(folioId);
        sourceEvent();
        schedule();
      } catch (error) {
        state.error =
          error instanceof Error
            ? error.message
            : "The latest manuscript could not be loaded.";
      } finally {
        applying = false;
        emit();
      }
    },
    refreshProof() {
      if (!destroyed) void compile();
    },
    destroy() {
      if (destroyed) return;
      if (state.dirty) draft();
      destroyed = true;
      cancel();
      releaseProof();
      editor.off("update", editorUpdated);
      window.removeEventListener(FOLIO_CONTENT_SAVED, saved);
      window.removeEventListener("twyne:typst-remote-change", remoteChanged);
      window.removeEventListener("twyne:request-typst-source", requestSource);
      if (!editor.isDestroyed && editor.isEditable !== !options.readOnly)
        editor.setEditable(!options.readOnly, false);
    },
  };
}
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
// @ts-expect-error jsdom is intentionally untyped in this project.
import { JSDOM } from "jsdom";
import type { Editor } from "@tiptap/core";
import {
  createTypstSession,
  type TypstSessionState,
  type TypstSessionDependencies,
} from "./session";
import { htmlToTypst } from "./document";
import { FOLIO_CONTENT_SAVED, type FolioContentSnapshot } from "../idb";
import type { ExportPayload } from "../exchange";

const previous = new Map<string, PropertyDescriptor | undefined>();
beforeAll(() => {
  const dom = new JSDOM("", { url: "https://twyne.test" });
  for (const key of ["window", "document", "DOMParser", "CustomEvent"]) {
    previous.set(key, Object.getOwnPropertyDescriptor(globalThis, key));
    Object.defineProperty(globalThis, key, {
      configurable: true,
      writable: true,
      value: dom.window[key],
    });
  }
});
afterAll(() => {
  for (const [key, descriptor] of previous) {
    if (descriptor) Object.defineProperty(globalThis, key, descriptor);
    else Reflect.deleteProperty(globalThis, key);
  }
});

async function setup(overrides: Partial<TypstSessionDependencies> = {}) {
  let html = "<p>Initial</p>";
  let editable = true;
  const listeners = new Set<() => void>();
  const states: TypstSessionState[] = [];
  const saved: string[] = [];
  let snap: FolioContentSnapshot = {
    folioId: "folio",
    html,
    typstSource: htmlToTypst(html),
    format: "typst",
    updatedAt: 1,
  };
  const editor = {
    getHTML: () => html,
    get isEditable() {
      return editable;
    },
    setEditable: (value: boolean, emitUpdate = true) => {
      editable = value;
      if (emitUpdate) listeners.forEach((fn) => fn());
    },
    on: (_: string, callback: () => void) => listeners.add(callback),
    off: (_: string, callback: () => void) => listeners.delete(callback),
    commands: {
      setContent: (value: string, options: { emitUpdate: boolean }) => {
        html = value;
        if (options.emitUpdate) listeners.forEach((fn) => fn());
      },
    },
    isDestroyed: false,
  } as unknown as Editor;
  const session = await createTypstSession(
    {
      editor,
      folioId: "folio",
      readOnly: false,
      onState: (state) => states.push(state),
      onPages: () => {},
      getPayload: async () => ({ html, title: "Test" }) as ExportPayload,
    },
    {
      loadSnapshot: async () => snap,
      saveSource: async (_id, source, body, expected) => {
        if ((snap.typstSource ?? null) !== expected)
          throw new Error("The manuscript changed");
        saved.push(source);
        snap = { ...snap, typstSource: source, html: body! };
      },
      loadDraft: async () => null,
      saveDraft: async () => {},
      clearDraft: async () => {},
      saveRevision: async () => null,
      compile: async () => ({
        pdf: new Blob(["PDF"]),
        pages: ['<svg xmlns="http://www.w3.org/2000/svg"/>'],
        pageCount: 1,
      }),
      ...overrides,
    },
  );
  return {
    session,
    states,
    saved,
    get html() {
      return html;
    },
    get editable() {
      return editable;
    },
    edit(value: string) {
      html = value;
      listeners.forEach((fn) => fn());
    },
    setSnapshot(value: FolioContentSnapshot) {
      snap = value;
    },
    get snapshot() {
      return snap;
    },
  };
}

describe("Typst source session", () => {
  test("only a successfully compiled source replaces the manuscript", async () => {
    let fail = true;
    const t = await setup({
      compile: async () => {
        if (fail) throw new Error("Syntax error at line 1");
        return { pdf: new Blob(["PDF"]), pages: [], pageCount: 1 };
      },
    });
    try {
      t.session.changeSource("= New title");
      expect(t.editable).toBe(false);
      await t.session.apply();
      expect(t.html).toBe("<p>Initial</p>");
      expect(t.saved).toHaveLength(0);
      expect(t.states.at(-1)?.error).toContain("Syntax error");
      fail = false;
      await t.session.apply();
      expect(t.html).toBe("<h1>New title</h1>");
      expect(t.saved).toEqual(["= New title"]);
      expect(t.editable).toBe(true);
    } finally {
      t.session.destroy();
    }
  });
  test("a delayed visual save never overwrites later keystrokes", async () => {
    const t = await setup();
    try {
      t.edit("<p>First edit</p>");
      const first = {
        ...t.snapshot,
        html: t.html,
        typstSource: htmlToTypst(t.html),
      };
      t.edit("<p>Second edit</p>");
      window.dispatchEvent(
        new CustomEvent(FOLIO_CONTENT_SAVED, { detail: first }),
      );
      expect(t.html).toBe("<p>Second edit</p>");
      expect(t.states.at(-1)?.source).toContain("Second edit");
    } finally {
      t.session.destroy();
    }
  });
  test("remote source conflicts preserve an unapplied draft", async () => {
    const t = await setup();
    try {
      t.session.changeSource("My local source");
      window.dispatchEvent(
        new CustomEvent("twyne:typst-remote-change", {
          detail: {
            folioId: "folio",
            source: "Remote source",
            html: "<p>Remote source</p>",
          },
        }),
      );
      expect(t.states.at(-1)?.conflict).toBe(true);
      expect(t.states.at(-1)?.source).toBe("My local source");
      expect(t.html).toBe("<p>Initial</p>");
      await t.session.apply();
      expect(t.saved).toHaveLength(0);
    } finally {
      t.session.destroy();
    }
  });
  test("recovers pending source and exposes it to export without replacing rich content", async () => {
    const t = await setup({
      loadDraft: async () => ({
        folioId: "folio",
        source: "#broken(",
        baseSource: htmlToTypst("<p>Initial</p>"),
        updatedAt: 1,
      }),
    });
    try {
      const detail = { folioId: "folio", source: "", pending: false };
      window.dispatchEvent(
        new CustomEvent("twyne:request-typst-source", { detail }),
      );
      expect(detail).toEqual({
        folioId: "folio",
        source: "#broken(",
        pending: true,
      });
      expect(t.html).toBe("<p>Initial</p>");
      expect(t.editable).toBe(false);
      await t.session.discard();
      expect(t.states.at(-1)?.dirty).toBe(false);
      expect(t.editable).toBe(true);
    } finally {
      t.session.destroy();
    }
  });
  test("remote changes preserve unsaved visual typing as a recovery draft", async () => {
    const t = await setup();
    try {
      t.edit("<p>Local unsaved typing</p>");
      const remote = {
        folioId: "folio",
        source: "Remote source",
        html: "<p>Remote source</p>",
      };
      window.dispatchEvent(
        new CustomEvent(FOLIO_CONTENT_SAVED, {
          detail: { ...remote, typstSource: remote.source },
        }),
      );
      window.dispatchEvent(
        new CustomEvent("twyne:typst-remote-change", { detail: remote }),
      );
      expect(t.html).toBe("<p>Local unsaved typing</p>");
      expect(t.states.at(-1)?.source).toContain("Local unsaved typing");
      expect(t.states.at(-1)?.dirty).toBe(true);
      expect(t.states.at(-1)?.conflict).toBe(true);
    } finally {
      t.session.destroy();
    }
  });
  test("a commit completing after folio switch still announces sync and clears recovery", async () => {
    let begin!: () => void;
    let finish!: () => void;
    const began = new Promise<void>((resolve) => {
      begin = resolve;
    });
    const finished = new Promise<void>((resolve) => {
      finish = resolve;
    });
    let cleared = 0;
    let committed = 0;
    const listener = () => committed++;
    window.addEventListener("twyne:typst-source-committed", listener);
    const t = await setup({
      saveSource: async () => {
        begin();
        await finished;
      },
      clearDraft: async () => {
        cleared++;
      },
    });
    try {
      t.session.changeSource("= Saved after switching");
      const applying = t.session.apply();
      await began;
      t.session.destroy();
      finish();
      await applying;
      expect(committed).toBe(1);
      expect(cleared).toBe(1);
      expect(t.html).toBe("<p>Initial</p>");
    } finally {
      t.session.destroy();
      window.removeEventListener("twyne:typst-source-committed", listener);
    }
  });
  test("a superseded compilation cannot replace the newest proof", async () => {
    const jobs: Array<{
      signal?: AbortSignal;
      finish: (pages: number) => void;
    }> = [];
    const t = await setup({
      compile: async (_source, options) =>
        new Promise((resolve) =>
          jobs.push({
            signal: options?.signal,
            finish: (count) =>
              resolve({
                pdf: new Blob([String(count)]),
                pages: [],
                pageCount: count,
              }),
          }),
        ),
    });
    try {
      t.session.refreshProof();
      await Promise.resolve();
      t.session.changeSource("New source");
      t.session.refreshProof();
      await Promise.resolve();
      expect(jobs).toHaveLength(2);
      expect(jobs[0].signal?.aborted).toBe(true);
      jobs[1].finish(2);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
      jobs[0].finish(1);
      await Promise.resolve();
      await Promise.resolve();
      await Promise.resolve();
      expect(t.states.at(-1)?.status).toBe("2 pages · source draft");
    } finally {
      t.session.destroy();
    }
  });
});

